const BULX={};
BUL.forEach(([id,g,n,c,ap,d,ea,r,h,i,ge,am,at])=>{
 const it={g,t:n,src:'Bulas · UpToDate · Sanford · Beers 2023 · LactMed',k:norm(n+' '+c+' '+ap+' efeitos adversos ajuste renal hepatico idoso gestacao amamentacao bula medicamento remedio'),sec:[
  {h:'Resumo',rows:[['Classe',c],['Apresentações',ap],['Dose usual',d]]},
  {h:'Efeitos adversos principais',li:ea.split(';').map(s=>s.trim()).filter(Boolean)},
  {h:'Ajustes',rows:[['Renal',r],['Hepático',h],['Idoso',i],['Gestação',ge],['Amamentação',am]].filter(x=>x[1])}]};
 if(at)it.sec.push({h:'Atenção',li:at.split(';').map(s=>s.trim()).filter(Boolean)});
 EX['med_'+id]=it;BULX[id]={n,ea,r,h,i,ge,am}});
/* Ficha do bulário para um nome de remédio da receita. Tópicos e colírios só com ficha explícita (b). */
const BULALIAS=[[/clavulanato/,'amoxclav'],[/^penicilina v/,'penicilinav'],[/^aas /,'aas'],[/^sulfato ferroso/,'sulfatoferroso'],[/^acido tranexamico/,'tranexamico'],[/^butilbrometo/,'escopolamina'],[/^valaciclovir/,'aciclovir'],[/^(prednisona|prednisolona)/,'prednisona'],[/^(gliclazida|glibenclamida)/,'sulfonilureia'],[/^(cinarizina|flunarizina)/,'cinarizina'],[/^(loratadina|desloratadina)/,'loratadina']];
function bulFor(name){const n=norm(name);
  if(/creme|pomada|colirio|otologic|spray nasal|gel vaginal|locao|cloreto de sodio|sais para/.test(n))return null;
  for(const [re,id] of BULALIAS)if(re.test(n))return id;
  const w=n.split(/[ (]/)[0];if(w.length<4||/^(acido|sulfato|cloreto)$/.test(w))return null;
  const b=BUL.find(b=>norm(b[2]).split(/\s*[\/(]\s*/).some(k=>k.split(' ')[0]===w));return b?b[0]:null}
